:root{--p-bg:#f7f9fc;--p-surface:#fff;--p-fg:#1b2440;--p-muted:#63708c;--p-primary:#3169ed;--p-line:#dce3f0;--p-font:'IBM Plex Sans Arabic';--p-radius:16px;color-scheme:light}
body{background:var(--p-bg);color:var(--p-fg);font-family:var(--p-font),sans-serif}.app{max-width:1120px;margin:auto;padding:24px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.brand{display:flex;align-items:center;gap:10px;font-weight:700}.brand-icon{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--p-primary);color:var(--p-surface)}.app-nav{display:flex;gap:6px;flex-wrap:wrap}.app button,.app input,.app select{font:inherit}.app button,.p-button{border:1px solid var(--p-line);background:var(--p-surface);color:var(--p-fg);padding:8px 16px;border-radius:10px}.app .primary{background:var(--p-primary);border-color:var(--p-primary);color:var(--p-surface)}.hero{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:28px;margin-bottom:20px;border:1px solid var(--p-line);border-radius:var(--p-radius);background:var(--p-surface)}.hero h1{font-size:30px;margin:0}.app h2{font-size:20px;margin:0 0 12px}.app h3{font-size:17px;margin:0 0 8px}.app p{margin:5px 0;color:var(--p-muted);font-size:14px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.project-card,.p-panel,.stat{padding:20px;border:1px solid var(--p-line);border-radius:var(--p-radius);background:var(--p-surface);min-width:0}.project-card{display:grid;gap:12px}.project-card .project-icon{font-size:22px}.meta,.p-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.p-badge{font-size:11px;border-radius:99px;padding:3px 9px;background:var(--p-bg);color:var(--p-primary);border:1px solid var(--p-line)}.dashboard-layout{display:grid;gap:20px}.dashboard-layout.side{grid-template-columns:1fr 2.6fr}.dashboard-layout.side .summary-stats{flex-direction:column}.dashboard-layout.side .cards{grid-template-columns:1fr 1fr}.dashboard-layout.focus .cards{grid-template-columns:2fr 1fr}.dashboard-layout.focus .project-card:first-child{grid-row:span 2}.dashboard-layout.focus .project-card:first-child h3{font-size:24px}.summary-stats{display:flex;gap:12px;flex-wrap:wrap}.stat{flex:1}.stat b{display:block;font-size:26px;color:var(--p-primary)}.task{padding:12px 0;border-bottom:1px solid var(--p-line);display:flex;align-items:center;gap:12px}.task:last-child{border:0}.check{width:16px;height:16px;border:1px solid var(--p-muted);border-radius:4px}.list-layout .cards{grid-template-columns:1fr}.list-layout .project-card{grid-template-columns:1fr 2fr auto;align-items:center}.gallery-layout .project-card{padding:0;overflow:hidden}.card-cover{height:100px;background:linear-gradient(135deg,var(--p-primary),var(--p-muted));padding:20px;color:var(--p-surface)}.gallery-layout .project-card .card-body{padding:20px}.detail-layout{display:grid;gap:20px}.detail-layout.side{grid-template-columns:2fr 1fr}.tab-bar{display:flex;gap:10px;border-bottom:1px solid var(--p-line);padding-bottom:10px}.tab-bar button:first-child{border-color:var(--p-primary);color:var(--p-primary)}.timeline-item{border-inline-start:2px solid var(--p-line);padding:0 20px 20px}.timeline-item:last-child{padding-bottom:0}.form-layout{display:grid;gap:16px}.form-layout label{display:grid;gap:6px;font-size:13px}.form-layout input{width:100%;border:1px solid var(--p-line);background:var(--p-bg);color:var(--p-fg);border-radius:10px;padding:12px}.form-layout.columns{grid-template-columns:1fr 1fr}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:16px}.board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.board-lane{background:var(--p-bg);padding:12px;border-radius:12px}.board-lane h3{font-size:14px}.board-task{background:var(--p-surface);padding:14px;border:1px solid var(--p-line);border-radius:10px;margin-bottom:10px;font-size:13px}.empty-space{height:16px}.dense .project-card{padding:12px;gap:6px}.airy .project-card{padding:28px;gap:18px}.app-footer{font-size:12px;color:var(--p-muted);margin-top:24px}.search-bar{display:flex;gap:12px;align-items:center;margin-bottom:16px}.search-bar input{flex:1;min-width:0;border:1px solid var(--p-line);background:var(--p-surface);padding:10px 14px;border-radius:10px;color:var(--p-fg)}.save-action{padding:16px;display:flex;align-items:center;gap:12px}.demo-button[data-demo]{transition:transform .2s,box-shadow .2s}.hover-demo:hover{transform:translateY(-3px);box-shadow:0 8px 16px #0002}html[data-playing=true] .press-demo{animation:press-demo .6s}html[data-playing=true] .progress-demo::after{content:' ✓';animation:feedback-demo .8s both}@keyframes press-demo{50%{transform:scale(.92)}}@keyframes feedback-demo{from{opacity:0}to{opacity:1}}@media(max-width:640px){.app{padding:16px}.topbar,.hero{align-items:stretch;flex-direction:column}.hero{padding:20px}.hero h1{font-size:24px}.cards,.dashboard-layout.side,.dashboard-layout.focus .cards,.detail-layout.side,.form-layout.columns{grid-template-columns:1fr}.list-layout .project-card{grid-template-columns:1fr}.board{grid-template-columns:1fr}.dashboard-layout.focus .project-card:first-child{grid-row:auto}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

.login-screen{min-height:100vh;display:grid;place-items:center}.login-card{width:min(100%,440px);padding:38px}.login-card h1{font-size:30px;margin:28px 0 24px}.login-card .form-layout{gap:18px}.login-card .primary{margin-top:8px;padding:12px}.login-caption{font-size:12px!important;margin-top:22px!important;text-align:center}@media(max-width:640px){.login-card{padding:26px}.login-card h1{font-size:26px}}
